<style>
.ytd-report{color:#172638;font-size:14px}.ytd-panel{border:1px solid #dce3ed;border-radius:16px;background:#fff;padding:24px;margin:0 0 20px}.ytd-title{font-size:24px;font-weight:750;margin:0 0 8px}.ytd-muted{color:#58687e;font-size:13px;line-height:1.6}.ytd-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.ytd-number{font-size:36px;font-weight:750;margin:8px 0}.ytd-change{font-size:16px;font-weight:700}.ytd-increase{color:#a13231}.ytd-decrease{color:#17644b}.ytd-neutral{color:#475569}.ytd-table{border-collapse:collapse;width:100%;font-size:13px}.ytd-table th,.ytd-table td{padding:11px 12px;border-bottom:1px solid #e4e9f0;text-align:left}.ytd-table th{background:#f2f6fb;font-weight:650}.ytd-table caption{text-align:left;font-size:17px;font-weight:700;padding:0 0 12px}.ytd-scroll{overflow-x:auto}.ytd-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:16px}.ytd-chart{display:flex;gap:14px;align-items:end;min-height:205px;overflow-x:auto;padding:15px 0}.ytd-chart-month{min-width:44px;flex:1;text-align:center}.ytd-bars{height:160px;display:flex;align-items:end;justify-content:center;gap:4px}.ytd-bar{display:block;width:16px;min-height:2px;border-radius:4px 4px 0 0}.ytd-current{background:#1d4ed8}.ytd-previous{background:#94a3b8}.ytd-legend{display:flex;gap:20px;font-size:12px;color:#475569}.ytd-key{display:inline-block;width:12px;height:12px;border-radius:3px;margin-right:5px}.ytd-link{display:inline-block;border:1px solid #bdcce1;border-radius:9px;padding:10px 16px;font-weight:650;color:#174cb2;text-decoration:none}.ytd-controls{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.ytd-controls label{font-size:13px;font-weight:600}.ytd-controls select,.ytd-controls input{display:block;border:1px solid #cbd5e1;border-radius:8px;padding:9px;margin-top:5px}.ytd-controls button{background:#1d4ed8;color:white;border:0;border-radius:8px;padding:10px 16px;font-weight:700}.ytd-heading{font-size:18px;font-weight:700;margin-bottom:12px}@media print{body{margin:0;font:12px Arial,sans-serif}.ytd-panel{border-radius:0;padding:12px;margin-bottom:12px}.ytd-number{font-size:27px}.ytd-cards{grid-template-columns:repeat(3,1fr)}.ytd-table{font-size:11px}.ytd-table th,.ytd-table td{padding:6px}.ytd-scroll{overflow:visible}thead{display:table-header-group}tr,.ytd-cards{break-inside:avoid}.ytd-no-print{display:none}.ytd-chart{overflow:visible}.ytd-panel{break-inside:auto}}@page{size:A4 landscape;margin:12mm}
</style>
